export interface ProblemEntry {
    path: string;
    title: string;
    description: string;
}
export interface ProblemReport {
    projectPath: string;
    problems: ProblemEntry[];
    errors: Array<{
        error: string;
    }>;
}
export type Result<T, E = Error> = {
    ok: true;
    value: T;
} | {
    ok: false;
    error: E;
};
export declare function runProblemCheck(projectPath: string): Promise<Result<ProblemReport, Error>>;
